  const b = bullets.find(b => !b.active); if (!b) return null;
  Object.assign(b, { x, y, vx, vy, r, team, active: true }); return b;
}
function updateBullets(dt, W, H) {
  for (const b of bullets) {
    if (!b.active) continue;
